function openCourse(id,pushHash=true){
  if(id==='welcome-orientation') return openOrientationCourse(pushHash);
  if(id==='foundations-natural-health') return openNaturalHealthCourse(pushHash);
  if(id==='biblical-faith-health') return openBiblicalFaithCourse(pushHash);
  const c=findCourse(id); if(!c)return;
  state.currentCourse=id; state.currentLesson=null;
  const req=c.requirements?.length?`<div class="card"><h3>Practitioner requirements</h3><div class="requirements">${c.requirements.map(x=>`<span class="req">${esc(x)}</span>`).join('')}</div></div>`:'';
  document.getElementById('courseDetail').innerHTML=`
    <div class="backbar"><button class="backbtn" onclick="showSection('courses')">← All courses</button></div>
    <div class="detail-hero"><span class="badge">${esc(c.pathwayTitle)}</span><h2>${esc(c.title)}</h2><p>${esc(c.description)}</p></div>
    <div class="card"><h3>Learning outcomes</h3><ul class="outcomes">${c.outcomes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>${req}
    <div class="section-head"><div><h2>Lessons</h2><p>Open a lesson to begin studying.</p></div><small>${c.lessons.length} total</small></div>
    <div class="card-grid">${c.lessons.map((l,i)=>`<button class="card lesson-card" onclick="openLesson('${c.id}',${i})"><span class="lesson-number">${i+1}</span><span><h3>${esc(l[0])}</h3><p>${esc(l[1])}</p></span><span class="arrow">›</span></button>`).join('')}</div>`;
  showSection('course-detail',false); if(pushHash)history.pushState(null,'',`#course/${id}`);
}

function openOrientationModule(n,pushHash=true){
  const m=moduleByNumber(n); if(!m)return;
  const extras=[];
  if(m.extras.reflection) extras.push(`<div class="card assignment-card"><span class="badge">Reflection</span><h3>Module ${m.number} Reflection</h3>${renderBlocks(m.extras.reflection)}</div>`);
  if(m.extras.assignment) extras.push(`<div class="card assignment-card"><span class="badge">Assignment</span><h3>Module ${m.number} Assignment</h3>${renderBlocks(m.extras.assignment)}</div>`);
  if(m.extras.final_assignment) extras.push(`<div class="card assignment-card"><span class="badge">Final Portfolio</span><h3>Final Orientation Assignment</h3>${renderBlocks(m.extras.final_assignment)}</div>`);
  if(m.extras.final_agreement) extras.push(`<div class="card assignment-card"><span class="badge">Required Agreement</span><h3>Final Orientation Agreement</h3>${renderBlocks(m.extras.final_agreement)}</div>`);
  document.getElementById('lessonDetail').innerHTML=`
    <div class="backbar"><button class="backbtn" onclick="openOrientationCourse()">← Welcome & Orientation</button></div>
    <div class="detail-hero"><span class="badge">Module ${m.number} of 10</span><h2>${esc(m.title)}</h2><p>${esc((m.purpose||[]).join(' '))}</p></div>
    <div class="card"><h3>Learning objectives</h3><ul class="outcomes">${m.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>
    <div class="section-head"><div><h2>Module Lessons</h2><p>Read each lesson in order.</p></div><small>${m.lessons.length} lessons</small></div>
    <div class="card-grid">${m.lessons.map((l,i)=>`<button class="card lesson-card" onclick="openOrientationLesson(${m.number},${i})"><span class="lesson-number">${esc(l.number)}</span><span><h3>${esc(l.title)}</h3><p>${lessonStatus(m.number,i)}</p></span><span class="arrow">›</span></button>`).join('')}</div>
    ${extras.join('')}
    ${m.number===10?`<div class="card assessment-promo"><span class="badge">Final Assessment</span><h3>Complete the orientation assessment</h3><p>25 open-book questions • 70% minimum passing score.</p><button class="btn btn-green" onclick="openOrientationAssessment()">Take assessment</button></div>`:''}`;
  showSection('lesson-detail',false); if(pushHash)history.pushState(null,'',`#orientation/module/${m.number}`);
}

function lessonKey(moduleNum,index){ return `${moduleNum}-${index}`; }
function lessonStatus(moduleNum,index){
  const complete=JSON.parse(localStorage.getItem('nhmec-orientation-complete')||'{}');
  return complete[lessonKey(moduleNum,index)] ? '✓ Completed' : 'Open lesson';
}
function toggleOrientationComplete(moduleNum,index){
  const complete=JSON.parse(localStorage.getItem('nhmec-orientation-complete')||'{}');
  const key=lessonKey(moduleNum,index); complete[key]=!complete[key]; localStorage.setItem('nhmec-orientation-complete',JSON.stringify(complete));
  openOrientationLesson(moduleNum,index,false);
}

function openOrientationLesson(moduleNum,index,pushHash=true){
  const m=moduleByNumber(moduleNum); if(!m||!m.lessons[index])return; const l=m.lessons[index];
  const complete=JSON.parse(localStorage.getItem('nhmec-orientation-complete')||'{}'); const done=!!complete[lessonKey(moduleNum,index)];
  let next='';
  if(index<m.lessons.length-1) next=`<button class="btn btn-green" onclick="openOrientationLesson(${moduleNum},${index+1})">Next lesson →</button>`;
  else if(moduleNum<10) next=`<button class="btn btn-green" onclick="openOrientationModule(${moduleNum+1})">Next module →</button>`;
  else next=`<button class="btn btn-green" onclick="openOrientationAssessment()">Final assessment →</button>`;
  document.getElementById('lessonDetail').innerHTML=`
    <div class="backbar"><button class="backbtn" onclick="openOrientationModule(${moduleNum})">← Module ${moduleNum}</button></div>
    <div class="detail-hero"><span class="badge">Lesson ${esc(l.number)}</span><h2>${esc(l.title)}</h2><p>NHMEC 100 • Welcome & Orientation</p></div>
    <article class="card lesson-body real-lesson">${renderBlocks(l.content)}
      <div class="complete-box"><button class="btn ${done?'btn-sage':'btn-green'}" onclick="toggleOrientationComplete(${moduleNum},${index})">${done?'✓ Lesson completed — tap to undo':'Mark lesson complete'}</button></div>
      <div class="lesson-nav"><button class="btn btn-sage" onclick="openOrientationModule(${moduleNum})">Module contents</button>${next}</div>
    </article>`;
  showSection('lesson-detail',false); if(pushHash)history.pushState(null,'',`#orientation/lesson/${moduleNum}/${index}`);
}

function openOrientationAssessment(pushHash=true){ state.orientationQuizIndex=0; state.orientationQuizScore=0; state.orientationAnswered=false; renderOrientationQuestion(); showSection('lesson-detail',false); if(pushHash)history.pushState(null,'','#orientation/assessment'); }
function renderOrientationQuestion(){
  const i=state.orientationQuizIndex, q=ORIENTATION.assessment_questions[i];
  if(!q){
    const pct=Math.round(state.orientationQuizScore/ORIENTATION.assessment_questions.length*100); const pass=pct>=70;
    document.getElementById('lessonDetail').innerHTML=`<div class="backbar"><button class="backbtn" onclick="openOrientationCourse()">← Welcome & Orientation</button></div><div class="detail-hero"><span class="badge">Assessment Complete</span><h2>${pass?'Passed — '+pct+'%':'Review & Retake — '+pct+'%'}</h2><p>You answered ${state.orientationQuizScore} of ${ORIENTATION.assessment_questions.length} correctly. NHMEC lists a 70% minimum passing score for this orientation assessment.</p></div><div class="card"><h3>${pass?'Orientation assessment passed':'Keep studying'}</h3><p>${pass?'You may continue into your assigned NHMEC learning pathway after completing the other required orientation acknowledgments and assignments.':'Review the modules, required reading, and scope language, then retake the open-book assessment.'}</p><button class="btn btn-green" onclick="openOrientationAssessment(false)">Retake assessment</button></div>`; return;
  }
  const pct=Math.round(i/ORIENTATION.assessment_questions.length*100);
  document.getElementById('lessonDetail').innerHTML=`<div class="backbar"><button class="backbtn" onclick="openOrientationCourse()">← Welcome & Orientation</button></div><div class="detail-hero"><span class="badge">Final Open-Book Assessment</span><h2>Question ${i+1} of ${ORIENTATION.assessment_questions.length}</h2><p>Passing score: 70% minimum.</p></div><div class="progress"><span style="width:${pct}%"></span></div><div class="quiz-card"><h3>${esc(q.q)}</h3><div id="orientationAnswers">${q.options.map(o=>`<button class="answer" onclick="answerOrientation('${o.letter}',this)"><b>${o.letter}.</b> ${esc(o.text)}</button>`).join('')}</div><div class="quiz-feedback" id="orientationFeedback"></div><button id="orientationNext" class="btn btn-green" style="display:none" onclick="nextOrientationQuestion()">${i===ORIENTATION.assessment_questions.length-1?'See results':'Next question'}</button></div>`;
}
function answerOrientation(letter,btn){
  if(state.orientationAnswered)return; state.orientationAnswered=true; const q=ORIENTATION.assessment_questions[state.orientationQuizIndex];
  const buttons=[...document.querySelectorAll('#orientationAnswers .answer')]; buttons.forEach((b,idx)=>{ if(q.options[idx].letter===q.correct)b.classList.add('correct'); });
  if(letter!==q.correct)btn.classList.add('wrong'); else state.orientationQuizScore++;
  document.getElementById('orientationFeedback').innerHTML=letter===q.correct?'<b>Correct.</b>':'<b>Review this item.</b> The correct answer is highlighted.';
  document.getElementById('orientationNext').style.display='inline-block';
}
function nextOrientationQuestion(){ state.orientationQuizIndex++; state.orientationAnswered=false; renderOrientationQuestion(); window.scrollTo({top:0,behavior:'smooth'}); }


